BUILD_OUTPUT_CONTRACTS.value:
## Required output payloads

`pr_summary`:

```ts
{
  pr_url: string;
  branch: string;
  base_branch: string;
  repository_key: string;
  summary: string;
}
```

`build_result`:

```ts
{
  summary: string;
  repository_key: string;
  changed_files: string[];
  tests: {
    passed: number;
    failed: number;
    output: string;
  };
  delegated_session_metadata: {
    cohort_id: string;
  };
  known_issues: Array<{
    description: string;
    severity: "blocking" | "warning" | "info";
  }>;
}
```
